--- 当随机概率高于successProbability概率时返回成功。
--- 否则它将返回失败。
--- successProbability应该在0和1之间

------------ import ------------
local Behavior = import("Frame.AI.BT.Behavior")
------------ import ------------

------------ define ------------

------------ define ------------

---@class RandomProbability
local RandomProbability = Class("RandomProbability", Behavior)

function RandomProbability:__init(successProbability)
    Behavior.__init(self)
    self.discriminator = "IConditional"

    self.btType = Behavior.BehaviorTreeType.Conditional
    self._successProbability = successProbability
end

function RandomProbability:__delete()

end

function RandomProbability:Update(context)
    if math.random(0, 1) > self._successProbability then
        return Behavior.TaskStatus.Success
    end
    return Behavior.TaskStatus.Failure
end

return RandomProbability
 